script:
(function () {
  'use strict';
  // Sector rebalancing. With T = current total + new cash and target weight w for each sector:
  //   current weight = value ÷ current total; difference = current weight − target (percentage points)
  //   Buy and sell: trade = w × T − value (sells and buys net to the new cash).
  //   Buy only: the new cash is split across underweight sectors in proportion to each one's
  //   shortfall (w × T − value); nothing is sold.
  //   Portfolio off target = half the sum of |difference|, i.e. the share of the portfolio that would
  //   have to move to match the targets.
  // Checks (scratchpad tests/sector-balance.test.js): default $100,000 portfolio, technology 32% vs
  // 25% target = sell $7,000; total sells = total buys = $9,000; off target 9.0%. Two sectors $60k/$40k,
  // 50/50 targets, $20k new cash buy-only = $20,000 into the $40k sector, ending exactly 50/50.
  // Fixes vs the old site: tickers were written into the page as raw HTML; funds were filed under
  // made-up "sectors" (S&P 500 Index, Total Market) that always looked out of balance; the benchmark
  // weights were hard-coded and dated. Targets are now the user's own and the tool gives dollar trades.
  var SECTORS = ['Information technology', 'Health care', 'Financials', 'Consumer discretionary', 'Communication services',
    'Industrials', 'Consumer staples', 'Energy', 'Utilities', 'Real estate', 'Materials', 'Other or unclassified'];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pts(v) {
    if (Math.abs(v) < 0.005) v = 0;
    return (v > 0 ? '+' : '') + v.toFixed(2) + ' pts';
  }

  function rebalance(values, targets, cash, buyOnly) {
    var total = values.reduce(function (a, b) { return a + b; }, 0), after = total + cash;
    var rows = values.map(function (v, i) {
      var cur = total > 0 ? v / total * 100 : 0;
      return { i: i, value: v, current: cur, target: targets[i], diff: cur - targets[i], trade: targets[i] / 100 * after - v };
    });
    if (buyOnly) {
      var short = rows.reduce(function (a, r) { return a + Math.max(0, r.trade); }, 0);
      rows.forEach(function (r) { r.trade = short > 0 ? cash * Math.max(0, r.trade) / short : 0; });
    }
    rows.forEach(function (r) { r.after = after > 0 ? (r.value + r.trade) / after * 100 : 0; });
    var drift = rows.reduce(function (a, r) { return a + Math.abs(r.diff); }, 0) / 2;
    var sell = rows.reduce(function (a, r) { return a + Math.max(0, -r.trade); }, 0);
    var buy = rows.reduce(function (a, r) { return a + Math.max(0, r.trade); }, 0);
    return { total: total, after: after, rows: rows, drift: drift, sell: sell, buy: buy };
  }

  function read() {
    var values = [], targets = [];
    for (var i = 0; i < SECTORS.length; i++) {
      var v = num('sbV' + i), t = num('sbT' + i);
      values.push(document.getElementById('sbV' + i).value.trim() === '' ? 0 : v);
      targets.push(document.getElementById('sbT' + i).value.trim() === '' ? 0 : t);
    }
    return { values: values, targets: targets };
  }

  function sum(a) { return a.reduce(function (x, y) { return x + y; }, 0); }

  function update() {
    var d = read(), cash = num('sbCash'), band = num('sbBand'), buyOnly = document.getElementById('sbMode').value === 'buy';
    var error = document.getElementById('sbError'), msg = '';
    var bad = d.values.concat(d.targets).some(function (v) { return isNaN(v) || v < 0; });
    var tSum = bad ? NaN : sum(d.targets), vSum = bad ? NaN : sum(d.values);
    document.getElementById('sbTotalIn').textContent = isNaN(vSum) ? '–' : money.format(vSum);
    document.getElementById('sbTargetSum').textContent = isNaN(tSum) ? '–' : (Math.round(tSum * 100) / 100) + '%';
    if (bad) msg = 'Use numbers of 0 or more for every value and target.';
    else if (d.targets.some(function (t) { return t > 100; })) msg = 'A target cannot be more than 100%.';
    else if (Math.abs(tSum - 100) > 0.1) msg = 'Targets add up to ' + (Math.round(tSum * 100) / 100) + '%. Adjust them so they total 100%.';
    else if (isNaN(cash) || cash < 0) msg = 'New cash must be 0 or more.';
    else if (isNaN(band) || band < 0 || band > 50) msg = 'Enter a tolerance band from 0 to 50 points.';
    else if (vSum <= 0) msg = 'Enter the current value of at least one sector.';
    else if (buyOnly && cash <= 0) msg = 'Buy-only rebalancing needs some new cash to invest.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var r = rebalance(d.values, d.targets, cash, buyOnly);
    var shown = r.rows.filter(function (row) { return row.value > 0 || row.target > 0; });
    var outside = shown.filter(function (row) { return Math.abs(row.diff) > band + 1e-9; }).length;
    var over = shown.slice().sort(function (a, b) { return b.diff - a.diff; })[0];
    var under = shown.slice().sort(function (a, b) { return a.diff - b.diff; })[0];
    document.getElementById('sbDrift').textContent = r.drift.toFixed(1) + '%';
    document.getElementById('sbSell').textContent = money.format(r.sell);
    document.getElementById('sbBuy').textContent = money.format(r.buy);
    document.getElementById('sbOut').textContent = outside + ' of ' + shown.length;
    document.getElementById('sbAfterTotal').textContent = money.format(r.after);
    document.getElementById('sbOver').textContent = over && over.diff > 0.005 ? SECTORS[over.i] + ' (' + pts(over.diff) + ')' : 'None';
    document.getElementById('sbUnder').textContent = under && under.diff < -0.005 ? SECTORS[under.i] + ' (' + pts(under.diff) + ')' : 'None';
    document.getElementById('sbTable').innerHTML = shown.map(function (row) {
      var status = Math.abs(row.diff) <= band + 1e-9 ? 'Within band' : (row.diff > 0 ? 'Overweight' : 'Underweight');
      var trade = Math.abs(row.trade) < 0.5 ? '–' : (row.trade > 0 ? 'Buy ' : 'Sell ') + money.format(Math.abs(row.trade));
      return '<tr><th scope="row">' + SECTORS[row.i] + '</th><td>' + money.format(row.value) + ' (' + row.current.toFixed(2) + '%)</td><td>' +
             row.target.toFixed(2) + '%</td><td>' + pts(row.diff) + '</td><td>' + status + '</td><td>' + trade + '</td><td>' +
             row.after.toFixed(2) + '%</td></tr>';
    }).join('');
  }

  function setTargets(weights) {
    // Round to 2 decimals and put any rounding remainder on the largest weight so targets total 100.
    var rounded = weights.map(function (w) { return Math.round(w * 100) / 100; });
    var big = 0;
    rounded.forEach(function (w, i) { if (w > rounded[big]) big = i; });
    rounded[big] = Math.round((rounded[big] + 100 - sum(rounded)) * 100) / 100;
    rounded.forEach(function (w, i) { document.getElementById('sbT' + i).value = String(w); });
    update();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('sbEqual').addEventListener('click', function () {
      var d = read(), held = d.values.filter(function (v) { return v > 0; }).length;
      if (!held) return;
      setTargets(d.values.map(function (v) { return v > 0 ? 100 / held : 0; }));
    });
    document.getElementById('sbCopy').addEventListener('click', function () {
      var d = read(), total = sum(d.values.map(function (v) { return v > 0 ? v : 0; }));
      if (!(total > 0)) return;
      setTargets(d.values.map(function (v) { return v > 0 ? v / total * 100 : 0; }));
    });
    update();
  });
})();
